import subprocess
import os

# Check available modules related to QE/Espresso
print("=== Available modules (grep for espresso/qe) ===")
result = subprocess.run(['module', 'avail'], capture_output=True, text=True)
if result.returncode == 0:
    lines = result.stdout.split('\n')
    for line in lines:
        if any(kw in line.lower() for kw in ['espresso', 'qe', 'pw']):
            print(line)
else:
    print(f"module avail failed: {result.stderr}")

# Check if there's a QE installation in common Cray module paths
print("\n=== Checking common Cray module paths ===")
for base in ['/opt/cray/pe/modulefiles', '/usr/share/lmod/lmod/lmod.lua', '/opt/cray/pe/modulefiles/2024.06.01']:
    if os.path.exists(base):
        print(f"{base} exists")

# Check if pw.x exists in any Cray PE directory
print("\n=== Searching for pw.x in Cray PE directories ===")
for root in ['/opt/cray/pe', '/usr/local/cray']:  
    if os.path.exists(root):
        for dirpath, dirnames, filenames in os.walk(root):
            for f in filenames:
                if f == 'pw.x':
                    print(f"Found: {os.path.join(dirpath, f)}")

# Check environment variables that might point to QE
print("\n=== Relevant environment variables ===")
for var in ['ESPRESSO_TMPDIR', 'QE_HOME', 'ESPRUITE', 'CRAY_PE_DIR', 'MODULEPATH']:
    val = os.environ.get(var)
    if val:
        print(f"{var} = {val}")

print("\nDone.")

